CREATE TABLE connections (owner VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, account CHAR(32) CHARACTER SET ascii NOT NULL, ciphertext TEXT NOT NULL, updated VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE catalogs (owner VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, data JSON NOT NULL, revision INT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE annotations (owner VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, zone CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, rule CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, data JSON NOT NULL, PRIMARY KEY(owner,zone,rule)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, owner VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, action VARCHAR(80) NOT NULL, target VARCHAR(255) NOT NULL, `before` JSON NULL, outcome VARCHAR(80) NOT NULL, created VARCHAR(30) NOT NULL, INDEX idx_audit_owner_created(owner,created)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE limits (owner VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, `window` BIGINT UNSIGNED NOT NULL, `count` INT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE sessions (id CHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, owner VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, expires BIGINT UNSIGNED NOT NULL, INDEX idx_sessions_expires(expires)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE auth_attempts (`key` VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, `window` BIGINT UNSIGNED NOT NULL, `count` INT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
